INSERT INTO `cases_t` (`id`, `case_id`, `lang_id`, `title`, `description`, `overview_text`, `location`, `cooperation_period`, `meta_title`, `meta_description`, `extras`) VALUES
(1, 1, 1, 'Automated Invoice Processing', 'We automated the entire invoice processing workflow, reducing manual data entry by 95% and cutting processing time from 4 hours to under 10 minutes.', 'RPA automates repetitive tasks instantly, saving 30–50% of time spent on admin. We analyzed existing workflows, identified bottlenecks, and deployed a tailored automation solution that transformed operations.', 'Europe', '3 months', 'Automated Invoice Processing — SIDIS', 'We automated the entire invoice processing workflow, reducing manual data entry by 95% and cutting processing time from 4 hours to under 10 minutes.', '{\"challenges_text\":\"SIDIS helps SMEs replace manual, time-consuming processes with intelligent automation. From auditing workflows to integrating RPA with your existing systems, we streamline operations, reduce errors, and save your team valuable time and costs.\",\"tech_text\":\"To effectively automate tasks, our team selected a suite of technologies designed to enhance campaign management, customer engagement, and data analysis.\",\"solution_subtitle\":\"The Solution\",\"solution_title\":\"End-to-end automation and digital transformation delivered in parallel\",\"solution_text1\":\"<p>The range of services provided by SIDIS covers full-cycle product development and includes business analysis, product design, software architecture, data science, software development, quality assurance and implementation. Thanks to our ability to adjust the delivery volume quickly, <b>SIDIS has grown the dedicated team from 10 to 50 specialists<\\/b> in just the first three months of our partnership.<\\/p><ul><li>Full workflow audit and automation blueprint delivered in week one.<\\/li><li>Custom RPA bots deployed for invoice processing, data entry, and reporting.<\\/li><li>CRM integration connecting sales, support, and billing into one unified view.<\\/li><li>AI-powered dashboard providing real-time operational insights.<\\/li><\\/ul>\",\"solution_text2\":\"<ul><li>Continuous monitoring and optimisation of all automated workflows post-launch.<\\/li><li>Staff training programme to ensure smooth adoption across all departments.<\\/li><li>Scalable cloud infrastructure enabling rapid expansion without re-engineering.<\\/li><\\/ul><p>The client team appreciated that SIDIS acted as a technology consultant, contributing ideas and challenging requirements rather than following a standard outsourcing model. This approach aligns perfectly with fast-paced, growth-oriented businesses.<\\/p>\",\"solution_image\":\"\\/assets\\/img\\/projects\\/image-7.webp\",\"results_title\":\"Final Results\",\"results_text\":\"The automation programme delivered measurable ROI within the first quarter, with compounding benefits as more workflows were optimised.\",\"results\":[{\"title\":\"Agile Legacy Transitions\",\"text\":\"Modernized systems improve speed, accuracy, and cut costs. SIDIS seamlessly integrates new solutions to boost your business efficiency.\"},{\"title\":\"Integrated Data Ecosystems\",\"text\":\"Unified systems enhance data flow and improve decision-making. We integrate your tech stack for seamless data and better insights.\"},{\"title\":\"Adaptable Scalability Solutions\",\"text\":\"Scalable solutions are vital for growing businesses. SIDIS delivers adaptable systems that evolve with your business needs.\"},{\"title\":\"Advanced Automation Processes\",\"text\":\"Automated processes free up resources and drive growth. We automate key workflows so your team can focus on strategic work.\"}],\"results_image\":\"\\/assets\\/img\\/blog\\/Image-1.webp\",\"result_quote\":\"Their automation expertise helped us streamline several internal processes. We saw measurable efficiency improvements within weeks.\",\"result_user_name\":\"Michael Turner\",\"result_user_work\":\"CEO, Solaris Dynamics\",\"result_user_image\":\"\\/assets\\/img\\/reviews\\/image-1.webp\",\"result_linkedin\":\"#\",\"tech_items\":[{\"name\":\"Backend\\nDevelopment\",\"description\":\"We built a robust, scalable backend using Node.js and PostgreSQL, designed to handle high transaction volumes with minimal latency.\"},{\"name\":\"Frontend\\nDevelopment\",\"description\":\"React-based frontend delivers a seamless user experience across all devices with real-time data updates.\"},{\"name\":\"Database\\nManagement\",\"description\":\"PostgreSQL for structured data, Redis for caching — ensuring peak performance and reliability under load.\"},{\"name\":\"Cloud\\nInfrastructure\",\"description\":\"AWS-hosted infrastructure with auto-scaling, load balancing, and 99.9% uptime SLA.\"},{\"name\":\"AI &\\nAutomation\",\"description\":\"Machine learning models and RPA workflows automate repetitive tasks and surface actionable insights.\"}]}'),
(2, 2, 1, 'Streamlined Data, Faster Insights', 'Connected multiple data sources into a unified dashboard, enabling real-time reporting and eliminating manual data exports.', 'RPA automates repetitive tasks instantly, saving 30–50% of time spent on admin. We analyzed existing workflows, identified bottlenecks, and deployed a tailored automation solution that transformed operations.', 'Europe', '3 months', 'Streamlined Data, Faster Insights — SIDIS', 'Connected multiple data sources into a unified dashboard, enabling real-time reporting and eliminating manual data exports.', '{\"challenges_text\":\"SIDIS helps SMEs replace manual, time-consuming processes with intelligent automation. From auditing workflows to integrating RPA with your existing systems, we streamline operations, reduce errors, and save your team valuable time and costs.\",\"tech_text\":\"To effectively automate tasks, our team selected a suite of technologies designed to enhance campaign management, customer engagement, and data analysis.\",\"tech_items\":[{\"name\":\"Backend\\nDevelopment\",\"description\":\"We built a robust, scalable backend using Node.js and PostgreSQL, designed to handle high transaction volumes with minimal latency.\"},{\"name\":\"Frontend\\nDevelopment\",\"description\":\"React-based frontend delivers a seamless user experience across all devices with real-time data updates.\"},{\"name\":\"Database\\nManagement\",\"description\":\"PostgreSQL for structured data, Redis for caching — ensuring peak performance and reliability under load.\"},{\"name\":\"Cloud\\nInfrastructure\",\"description\":\"AWS-hosted infrastructure with auto-scaling, load balancing, and 99.9% uptime SLA.\"},{\"name\":\"AI &\\nAutomation\",\"description\":\"Machine learning models and RPA workflows automate repetitive tasks and surface actionable insights.\"}],\"solution_subtitle\":\"The Solution\",\"solution_title\":\"End-to-end automation and digital transformation delivered in parallel\",\"solution_text1\":