INSERT INTO `reviews_t` (`id`, `review_id`, `lang_id`, `quote`, `text`, `author_name`, `author_title`) VALUES
(1, 1, 1, 'They are truly experienced specialists who work in a well-coordinated way.', 'Sidis Group has delivered around 15 well-tested features, saving the client approximately 100 man-hours. The team has a well-structured process and communicates effectively. They\'re also professional, experienced, and organized. Overall, the client is very satisfied with Sidis Group\'s work.', 'Nikolay Popov', 'Head, AdKey.app'),
(2, 2, 1, 'There have never been any critical issues with timing or estimation.', 'Sidis Group has launched the client\'s MVP within the agreed timeline and budget. The team has deployed the platform into production with live users and improved operational efficiency due to optimized business processes. Moreover, Sidis Group has integrated key third-party providers.', 'Denis Gulagin', 'CEO & Founder, Bakksy'),
(3, 3, 1, 'Their genuine interest in the project was most impressive.', 'Sidis Group\'s completed the project quickly and on time. The team responded promptly to requests and handled all adjustments efficiently throughout the project. Moreover, they were highly engaged, proactive in suggesting improvements, and committed to achieving optimal results.', 'Dmytro Kaminskyi', 'IT Support Engineer for E-Commerce & Amazon, I\'m a Natural'),
(4, 4, 1, 'Finally, an automation partner that speaks our language.', 'We\'d tried other automation tools before but always hit walls. SIDIS took the time to understand our unique processes and built something truly custom.\n\nSix months later, our team handles 3× the volume with the same headcount. The support after delivery has also been excellent.', 'Sarah Mitchell', 'Head of Operations, NexaFlow');
