INSERT INTO `solution_items_t` (`id`, `item_id`, `lang_id`, `title`, `description`, `btn_text`, `btn_url`) VALUES
(1, 1, 1, 'Workflow Automations', 'We help SMEs automate repetitive tasks and optimise everyday processes. From mapping workflows to integrating automation tools with your existing systems, we save time, reduce errors, and improve operational efficiency.', 'Learn more', '#'),
(2, 2, 1, 'Custom Software Development', 'We help SMEs automate repetitive tasks and optimise everyday processes. From mapping workflows to integrating automation tools with your existing systems, we save time, reduce errors, and improve operational efficiency.', 'Learn more', '#'),
(3, 3, 1, 'Bespoke Software Solutions', 'We help SMEs automate repetitive tasks and optimise everyday processes. From mapping workflows to integrating automation tools with your existing systems, we save time, reduce errors, and improve operational efficiency.', 'Learn more', '#'),
(4, 4, 1, 'Operations Automation', 'We automate operational workflows so your team focuses on high-value work.', 'Learn more', '#'),
(5, 5, 1, 'Sales Automation', 'Automate your sales pipeline to close more deals with less manual effort.', 'Learn more', '#'),
(6, 6, 1, 'Marketing Automation', 'Scale your marketing efforts with intelligent automation tools.', 'Learn more', '#'),
(7, 7, 1, 'SaaS Startups', 'Purpose-built automation solutions to help SaaS companies scale efficiently.', 'Learn more', '#'),
(8, 8, 1, 'Ecommerce', 'Automate orders, inventory, and customer communication at scale.', 'Learn more', '#'),
(9, 9, 1, 'Affiliate Marketing', 'Automate partner tracking, payouts, and reporting pipelines.', 'Learn more', '#');
