INSERT INTO `solution_pages_t` (`id`, `page_id`, `lang_id`, `title`, `description`, `btn1_text`, `btn2_text`, `meta_title`, `meta_description`) VALUES
(1, 1, 1, 'Business process analysis & optimization', 'Map, analyse, and redesign your core business processes to eliminate waste, reduce cycle times, and build a foundation ready for automation and sustainable scale.', 'Learn more', 'Free audit', '', ''),
(2, 2, 1, 'Business process automation', 'Automate repetitive workflows — approvals, data entry, and notifications — with connected systems that eliminate bottlenecks and run reliably across your operations.', '', '', 'Business process automation', ''),
(3, 3, 1, 'AI implementation for business', 'Identify where AI fits your workflows and implement practical solutions — document processing, decision support, and predictive automation built around real operations.', '', '', 'AI implementation for business', ''),
(4, 4, 1, 'Custom CRM development', 'A CRM built for how you actually sell — not for everyone. Full ownership, no per-seat fees, and a system that fits your exact process and evolves with your business.', '', '', 'Custom CRM development', ''),
(5, 5, 1, 'Custom ERP development', 'An ERP built around how your company operates — connecting inventory, finance, and operations in one tailored platform with no unnecessary modules or vendor lock-in.', '', '', 'Custom ERP development', ''),
(6, 6, 1, 'Internal business systems development', 'Replace spreadsheets and workarounds with purpose-built portals, dashboards, and management tools integrated with your existing stack and designed for your team.', '', '', 'Internal business systems development', ''),
(7, 7, 1, 'SaaS platform development', 'Design and build scalable SaaS platforms from concept to launch — multi-tenancy, subscription management, and automation built in from the first line of code.', '', '', 'SaaS platform development', ''),
(8, 8, 1, 'Systems & API integrations', 'Connect your CRM, ERP, payment systems, and communication tools through custom integrations that eliminate manual data transfers and keep your stack in sync automatically.', '', '', 'Systems & API integrations', ''),
(9, 9, 1, 'Sales automation', 'Automate CRM updates, lead routing, follow-up sequences, and pipeline reports so your reps focus on closing deals instead of administrative tasks that slow them down.', '', '', 'Sales automation', ''),
(10, 10, 1, 'Marketing automation', 'Build systems that handle lead capture, nurturing sequences, segmentation, and campaign triggers — delivering the right message automatically at the right time.', '', '', 'Marketing automation', ''),
(11, 11, 1, 'Customer support automation', 'Automate ticket routing, first-response handling, and status updates so your support team focuses on complex issues and handles higher volume without adding headcount.', '', '', 'Customer support automation', ''),
(12, 12, 1, 'Operations automation', 'Replace manual handoffs and fragile tracking with automated workflows that run without supervision — making operations predictable, scalable, and ready to handle growth.', '', '', 'Operations automation', ''),
(13, 13, 1, 'Unified business management systems', 'Replace disconnected tools with a unified platform that brings operations, data, and workflows into one place — custom-built to your structure and integrated with existing systems.', '', '', 'Unified business management systems', ''),
(14, 14, 1, 'AI chatbots for business', 'Deploy AI chatbots that qualify leads, handle support, book meetings, and guide users through complex flows — 24/7, integrated with your existing systems.', '', '', 'AI chatbots for business', ''),
(15, 15, 1, 'Voice AI assistants', 'Build custom voice AI that handles inbound calls, qualifies leads, answers questions, and books appointments — 24/7 availability, integrated with your existing systems.', '', '', 'Voice AI assistants', ''),
(16, 16, 1, 'Data & reporting automation', 'Automate data pipelines and reporting so the right information reaches the right people on time, without the manual pull-and-format routine slowing your decisions.', '', '', 'Data & reporting automation', ''),
(17, 17, 1, 'Replacing manual work with automation', 'Audit your operations and replace predictable manual tasks — data entry, file transfers, copy-pasting — with background automations that free your team for strategic work.', '', '', 'Replacing manual work with automation', ''),
(18, 18, 1, 'Scaling business through automation', 'Build the automation infrastructure that lets your business handle more volume with the same team — fewer bottlenecks, connected systems, and processes that scale.', '', '', 'Scaling business through automation', ''),
(19, 19, 1, 'Operations', 'Automate handoffs, vendor management, project coordination, and internal reporting — making operations predictable and scalable without constant manual oversight.', '', '', 'Operations', ''),
(20, 20, 1, 'Sales', 'Automate CRM updates, lead assignment, follow-up sequences, and pipeline reports so your reps focus on selling rather than the administrative work that slows everything down.', '', '', 'Sales', ''),
(21, 21, 1, 'Marketing', 'Automate campaign setup, lead routing, content scheduling, and performance reporting so your marketing team focuses on strategy and creative rather than manual execution.', '', '', 'Marketing', ''),
(22, 22, 1, 'Customer Support', 'Automate ticket triage, routing, and first-response handling so your agents focus on complex issues while managing higher volume without adding operational headcount.', '', '', 'Customer Support', ''),
(23, 23, 1, 'Finance', 'Automate invoice processing, reconciliation, approvals, and financial reporting — eliminating manual data entry and enforcing consistent process across your finance team.', '', '', 'Finance', ''),
(24, 24, 1, 'HR', 'Automate onboarding, document collection, approvals, and employee data management to reduce administrative burden and free HR for strategic, people-focused work.', '', '', 'HR', ''),
(25, 25, 1, 'Recruitment', 'Automate interview scheduling, candidate communications, application routing, and document collection so recruiters focus on evaluation and relationship building.', '', '', 'Recruitment', ''),
(26, 26, 1, 'Product', 'Automate feedback routing, roadmap updates, release communication, and cross-team reporting so your product team spends time on decisions instead of information chasing.', '', '', 'Product', ''),
(27, 27, 1, 'IT / Engineering', 'Automate infrastructure provisioning, access management, incident workflows, and internal ticketing so engineers focus on technical work instead of operational overhead.', '', '', 'IT / Engineering', ''),
(28, 28, 1, 'Analytics / BI', 'Automate analytics and BI workflows — data collection, report generation, and dashboard updates — so your team acts on insights instead of spending time preparing data.', '', '', 'Analytics / BI', ''),
(29, 29, 1, 'Executive / Management', 'Surface consolidated reports, performance dashboards, and workflow alerts automatically so leadership has full visibility without waiting on manually compiled updates.', '', '', 'Executive / Management', ''),
(30, 30, 1, 'Legal', 'Automate contract workflows, document routing, deadline tracking, and compliance documentation to reduce turnaround times and free legal professionals for substantive work.', '', '', 'Legal', ''),
(31, 31, 1, 'Compliance', 'Automate document management, approval chains, deadline tracking, and audit trails to enforce consistent compliance process and reduce risk from manual handling.', '', '', 'Compliance', ''),
(32, 32, 1, 'Partnerships', 'Automate partner onboarding, communication workflows, activity tracking, and reporting so your team focuses on relationship building rather than coordination overhead.', '', '', 'Partnerships', ''),
(33, 33, 1, 'Affiliate Marketing', 'Automate partner onboarding, campaign tracking, commission calculation, and reporting to scale your affiliate program without growing your operations team proportionally.', '', '', 'Affiliate Marketing', ''),
(34, 34, 1, 'HR & Recruiting', 'Automate candidate sourcing, screening, scheduling, and client reporting so your agency scales operations without increasing the administrative headcount required.', '', '', 'HR & Recruiting', ''),
(35, 35, 1, 'Fintech', 'Automate KYC flows, transaction monitoring, compliance reporting, and operational processes to handle high volumes reliably while your team focuses on product and growth.', '', '', 'Fintech', ''),
(36, 36, 1, 'Real Estate', 'Automate lead follow-up, document management, transaction coordination, and CRM updates so your agents focus on deals and client relationships rather than manual admin.', '', '', 'Real Estate', ''),
(37, 37, 1, 'Retail', 'Automate order processing, inventory updates, fulfillment, and customer notifications to handle more orders at volume without adding operational staff proportionally.', '', '', 'Retail', ''),
(38, 38, 1, 'Ecommerce', '', '', '', 'Ecommerce', ''),
(39, 39, 1, 'Investment Management', 'Automate portfolio reporting, compliance documentation, client communications, and data aggregation so analysts focus on decisions rather than data assembly.', '', '', 'Investment Management', ''),
(40, 40, 1, 'Logistics', 'Automate shipment tracking, documentation, vendor communications, and reporting to reduce errors and maintain real-time visibility across every stage of your supply chain.', '', '', 'Logistics', ''),
(41, 41, 1, 'Wellness & Mental Health', 'Automate scheduling, intake forms, follow-up communications, billing, and reporting so practitioners spend more time on client care and less time on administrative tasks.', '', '', 'Wellness & Mental Health', ''),
(42, 42, 1, 'Lead Generation Agencies', 'Automate prospect sourcing, outreach sequences, lead qualification, and client delivery to generate more output with the same team at consistent, repeatable quality.', '', '', 'Lead Generation Agencies', ''),
(43, 43, 1, 'Marketing & Advertising', 'Automate client reporting, campaign workflows, approvals, and data aggregation so your agency handles more clients without growing the operations team proportionally.', '', '', 'Marketing & Advertising', ''),
(44, 44, 1, 'Agencies', '', '', '', 'Agencies', ''),
(45, 45, 1, 'LegalTech', 'Automate document processing, client onboarding, product operations, and reporting to build a scalable LegalTech business with strong compliance and operational efficiency.', '', '', 'LegalTech', ''),
(46, 46, 1, 'Arbitration Companies', 'Automate case intake, document management, scheduling, communications, and compliance tracking to enforce consistency and reduce administrative burden on every case.', '', '', 'Arbitration Companies', ''),
(47, 47, 1, 'SaaS Startups', 'Automate customer onboarding, billing, support workflows, and internal reporting to scale revenue without scaling headcount at the same rate as your user base grows.', '', '', 'SaaS Startups', ''),
(48, 48, 1, 'SMEs (general growing businesses)', 'Automate your sales, operations, and reporting workflows to handle more growth without the overhead increase that usually comes with scaling a business manually.', '', '', 'SMEs (general growing businesses)', ''),
(49, 49, 1, 'Procurement', 'Automate vendor onboarding, purchase orders, approval routing, invoice matching, and contract management to reduce errors and accelerate your procurement lifecycle.', 'Try AI assistant', 'Free audit', '', '');
INSERT INTO `sol_page_blocks` (`id`, `page_id`, `lang_id`, `block_key`, `label`, `sort_order`, `is_active`, `content`) VALUES
(1, 1, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Sidis Workflow Solutions\",\"text\":\"Explore our digital workflow solutions aimed at making employee workflow faster, more accurate, and very productive. Explore our digital workflow solutions aimed at making employee workflow faster, more accurate, and very productive.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":\"11\",\"image_url\":\"\\/uploads\\/20260518_145625_83ac0203.webp\",\"selected_ids\":[]}'),
(2, 1, 1, 'features', 'Features Slider', 1, 1, '{\"title\":\"What you get\",\"slides\":[{\"title\":\"Manual & Repetitive Tasks\",\"text\":\"RPA automates repetitive tasks instantly, saving 30–50% of time spent on admin.\"},{\"title\":\"Inaccurate Data & Human Errors\",\"text\":\"Automated workflows eliminate human error and ensure consistent data quality across all systems.\"},{\"title\":\"Slow Processes & Delays\",\"text\":\"Smart automation cuts processing times from hours to minutes, accelerating every workflow.\"},{\"title\":\"Lack of Integration Between Systems\",\"text\":\"We connect your tools so data flows automatically, removing silos and manual data entry.\"}]}'),
(3, 1, 1, 'planning', 'Planning / Process', 2, 1, '{\"items\":[{\"title\":\"Enterprise Resource Planning (ERP)\",\"text\":\"We help integrate a customized ERP system that includes specialized modules for inventory control, production scheduling, and supply chain management.\"},{\"title\":\"CRM Integration\",\"text\":\"Connect your customer data across all touchpoints for a unified view of every client relationship and interaction.\"}],\"info_title\":\"Curious which RPA solution fits your business needs?\",\"info_btn1_text\":\"Contact us\",\"info_btn1_url\":\"#getintouch\",\"info_btn2_text\":\"Free audit\",\"info_btn2_url\":\"#getintouch\",\"selected_ids\":[]}'),
(4, 1, 1, 'solved', 'Challenges Solved', 3, 1, '{\"title\":\"Business Challenges Solved with RPA\",\"slides\":[{\"title\":\"Maximise operational efficiency\",\"text\":\"Accelerate time-to-market and reduce operational costs while eliminating bottlenecks in processes. We implement solutions powered by machine learning and intelligent automation to optimize scheduling and resource allocation.\"},{\"title\":\"Make compliance-driven decisions\",\"text\":\"Minimize risks and avoid costly incidents with built-in controls embedded directly into your business processes. Our compliance management expertise delivers comprehensive audit trails and automated documentation.\"},{\"title\":\"Power business growth with integration\",\"text\":\"Grow your business by eliminating data silos that limit strategic decision-making. Our integrated software solutions unlock new revenue opportunities by connecting all your systems into a single platform.\"}],\"selected_ids\":[]}'),
(5, 1, 1, 'roadmap', 'Roadmap', 4, 1, '{\"title\":\"Our Development Process\",\"btn1_text\":\"Get PDF\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"steps\":[{\"title\":\"Discovery Call\",\"text\":\"Initial consultation. Project assessment. Solution overview.\"},{\"title\":\"Strategy & Proposal\",\"text\":\"Refine project scope. Define clear goals. Deliver tailored solutions.\"},{\"title\":\"Integration\",\"text\":\"Optimize workflows. Enhance collaboration. Accelerate growth.\"},{\"title\":\"Support, Monitor & Scale\",\"text\":\"Maximize uptime. Ensure peak performance. Drive continuous improvement.\"}],\"video_path\":\".\\/assets\\/video\\/compressed-v2\\/Video-cover-roadmap.mp4\",\"selected_ids\":[],\"video_poster\":\".\\/assets\\/video\\/compressed-v2\\/Video-cover-blog-roadmap-poster.webp\"}'),
