(9, 1, 1, 'faq', 'FAQ', 8, 1, '{\"title\":\"Questions & answers\",\"items\":[{\"q\":\"What are your pricing options?\",\"a\":\"Our team is based in Eastern Europe, which gives us an advantage in operational costs — low taxes, rent, and payroll. We maintain a compact team of professionals and pass the savings to our clients.\"},{\"q\":\"What is your typical project timeline?\",\"a\":\"Most automation projects take 4–8 weeks from discovery to deployment. Complex integrations may take longer. We provide a clear timeline in the proposal stage.\"},{\"q\":\"How do you handle customer feedback?\",\"a\":\"We work in iterative cycles with regular check-ins. Client feedback is incorporated at each stage, and we offer a post-launch support period for adjustments.\"},{\"q\":\"Can you provide case studies or testimonials?\",\"a\":\"Yes — see our Case Studies section and client testimonials below. We can also provide references upon request.\"}]}'),
(10, 1, 1, 'articles', 'Latest Articles', 9, 1, '{\"title\":\"Latest Automation\\nInsights\"}'),
(11, 4, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Custom CRM Development\",\"text\":\"Off-the-shelf CRMs are built for everyone, which means they\'re perfect for no one. If your team works around your CRM instead of with it, you need a system built for how you actually sell. We develop custom CRM solutions that match your exact sales process, automate pipeline management, and integrate with every tool your team uses. Full ownership, no per-seat fees growing with your headcount, and a system that evolves as your business does.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
