(51, 21, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Marketing Department Automation\",\"text\":\"Marketing teams manage complex multi-channel operations that generate significant repetitive work — campaign setup, lead routing, content scheduling, performance reporting, and tool synchronization. We automate your marketing workflows so your team focuses on strategy and creative work rather than manual execution. Connected systems that move leads through the right sequences, keep your stack in sync, and surface performance data automatically without the manual weekly pull that nobody enjoys.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
