(61, 9, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Sales Automation\",\"text\":\"Your sales team shouldn\'t spend half their day on admin. We automate the repetitive parts of your sales process — lead routing, follow-up sequences, CRM updates, pipeline management, and reporting — so reps stay focused on closing deals. From first touch to signed contract, we build systems that move prospects through your funnel faster with fewer things falling through the cracks. More pipeline activity, less administrative overhead holding your team back.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
