(111, 5, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Custom ERP Development\",\"text\":\"Generic ERP platforms often require you to adapt your business to fit the software. We flip that model — building ERP systems designed around how your company actually operates. From inventory and procurement to finance and operations, your custom ERP connects every department in one platform tailored to your workflows. No unnecessary modules, no workarounds, no vendor lock-in. Just a system that fits your business precisely and scales alongside it.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
