(121, 20, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Sales Department Automation\",\"text\":\"Sales teams are most effective when they\'re selling — not updating CRM records, writing follow-up emails, or pulling pipeline reports. We automate the administrative and operational work across your sales department: lead assignment, pipeline updates, follow-up sequences, proposal generation, and performance reporting. Your reps get hours back each week. Your managers get real-time visibility. Your pipeline moves faster with fewer things falling through the cracks between stages.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
