(181, 27, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"IT & Engineering Automation\",\"text\":\"IT teams are often the last to benefit from automation despite building it for everyone else. We help IT and engineering departments automate their own operations — infrastructure provisioning, incident response workflows, access management, deployment pipelines, and internal ticketing. Less manual overhead for your technical team, faster response times, and systems that handle routine operational tasks in the background so your engineers focus on work that requires their expertise.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
