(191, 28, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Analytics & BI Automation\",\"text\":\"Your data is only valuable when the right people have it at the right time. We automate analytics and BI workflows — from data collection and transformation to report generation and dashboard updates — so your team makes decisions instead of preparing spreadsheets. Custom dashboards, automated pipelines, and integrated reporting give every department real-time visibility into performance without the manual work that usually sits between raw data and actionable insight.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
