(211, 30, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Legal Department Automation\",\"text\":\"Legal teams handle high volumes of document-intensive work with strict accuracy requirements and tight deadlines. We automate the operational side of your legal department — contract management workflows, document routing, deadline tracking, approval chains, and compliance documentation. Systems that reduce turnaround times, enforce consistent process, and free your legal professionals to focus on substantive work rather than the administrative overhead that takes up too much of their day.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
