(241, 6, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Internal Business Systems Development\",\"text\":\"Most growing businesses run on a mix of workarounds, spreadsheets, and tools not designed for how they operate today. We build custom internal systems — portals, dashboards, workflow tools, and management platforms — that replace patchwork solutions with something reliable and purpose-built. Designed around your team\'s actual needs, integrated with your existing stack, and built to scale as your business grows and your processes become more complex and demanding.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
