(281, 12, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Operations Automation\",\"text\":\"Operational inefficiency hides in manual handoffs, spreadsheet tracking, and processes that only work because someone checks them every day. We identify those friction points and replace them with automated workflows that run without supervision. Approvals move on their own. Data stays in sync. Tasks get assigned automatically. Your operations become reliable, predictable, and ready to handle growth without adding overhead to keep everything running smoothly.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
