(291, 14, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"AI Chatbots for Business\",\"text\":\"A well-built AI chatbot does more than answer FAQs — it qualifies leads, handles support requests, books meetings, and guides users through complex processes without a human in the loop. We design and deploy business chatbots that understand your context, integrate with your existing systems, and handle real conversations at scale. Available 24\\/7, consistent across every interaction, and built to solve actual business problems rather than just look impressive on your website.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
