(321, 17, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Replacing Manual Work with Automation\",\"text\":\"If your team spends hours each week on tasks that follow a predictable pattern — data entry, file transfers, status updates, copy-pasting between systems — those are prime targets for automation. We audit your operations, identify the highest-impact manual tasks, and replace them with workflows that run reliably in the background. Less time on repetitive work means more capacity for strategic tasks, fewer human errors, and a team ready to scale.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
(322, 17, 1, 'features', 'Features Slider', 1, 1, '{\"title\":\"What you get\",\"slides\":[{\"title\":\"Manual & Repetitive Tasks\",\"text\":\"RPA automates repetitive tasks instantly, saving 30–50% of time spent on admin.\"},{\"title\":\"Inaccurate Data & Human Errors\",\"text\":\"Automated workflows eliminate human error and ensure consistent data quality across all systems.\"},{\"title\":\"Slow Processes & Delays\",\"text\":\"Smart automation cuts processing times from hours to minutes, accelerating every workflow.\"},{\"title\":\"Lack of Integration Between Systems\",\"text\":\"We connect your tools so data flows automatically, removing silos and manual data entry.\"}]}'),
