(361, 36, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Automation for Real Estate Companies\",\"text\":\"Real estate involves high-touch client relationships supported by a lot of repetitive operational work — property listings, document collection, transaction coordination, lead follow-up, and CRM management. We build automation systems for real estate businesses that handle routine workflow so your agents focus on deals and relationships. Automated follow-up sequences, document management, transaction tracking, and performance reporting that keep every deal moving without constant manual chasing from your team.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
