(451, 46, 1, 'promo', 'Hero / Promo', 0, 1, '{\"title\":\"Automation for Arbitration Companies\",\"text\":\"Arbitration firms manage document-heavy, deadline-driven processes where accuracy and consistency are non-negotiable. We automate the operational workflows of arbitration practices — case intake, document management, scheduling, party communications, compliance tracking, and reporting. Custom systems that enforce process consistency across all cases, reduce administrative burden on your team, and ensure nothing falls through the cracks during proceedings where the stakes are too high for process failures.\",\"btn1_text\":\"View Our Presentation\",\"btn1_url\":\"\\/assets\\/Sidis-Group.pdf\",\"btn2_text\":\"Free audit\",\"btn2_url\":\"#getintouch\",\"image_id\":null,\"image_url\":\"\"}'),
